-- ── story 3-5b: stock take with freeze ───────────────────────────────────
-- Generated by drizzle-kit (the tables, the three count_tasks columns and the
-- indexes — every index IF NOT EXISTS, guide §3) and hand-amended around the
-- generated part: the fail-fast guard, the CHECKs, the RLS policies and the
-- post-migration probe (drizzle-kit is blind to CHECKs and policies; `bun run
-- db:generate` afterwards reports "No schema changes").
--
--   * `stock_takes` (movements) — one row per take; `status` is
--     `counting | posting | closed | abandoned` (`STOCK_TAKE_STATUSES`,
--     schema.ts), pinned TS ↔ DB by test/stock-take-migration.spec.ts.
--   * `stock_freeze_bins` (inventory) — one row per frozen bin, unique on
--     (tenant, bin): the ledger append's freeze probe reads it under the
--     warehouse advisory; `device_writes` counts the handheld writes admitted
--     after the freeze (design review A1).
--   * `count_tasks` gains `stock_take_id`, `cancelled_by`, `cancelled_at`; its
--     status CHECK is dropped and re-added with `cancelled` — NOT VALID, since
--     `count_tasks` grows with every scheduler tick and the migrator runs the
--     whole pending set in one transaction (guide §3). Every existing row is
--     `pending` or `completed` with no `cancelled_at` (the column is new), so
--     both NOT VALID CHECKs hold by construction; their VALIDATEs are
--     bookkeeping for a later deploy (PENDING, deploy).
--   * the PENDING keyset index `(tenant_id, created_at, id)` for the web list,
--     and a partial index for a take's tasks by status.
--
-- Additive: two new tables, three nullable columns, no default — no rewrite.

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF to_regclass('public.stock_takes') IS NOT NULL OR to_regclass('public.stock_freeze_bins') IS NOT NULL THEN
		RAISE EXCEPTION 'migration 0107: stock_takes / stock_freeze_bins already exist — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE "stock_freeze_bins" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"warehouse_id" uuid NOT NULL,
	"bin_id" uuid NOT NULL,
	"bin_code" text NOT NULL,
	"stock_take_id" uuid NOT NULL,
	"frozen_at" timestamp with time zone NOT NULL,
	"device_writes" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "stock_takes" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"warehouse_id" uuid NOT NULL,
	"zone_ids" jsonb,
	"status" text DEFAULT 'counting' NOT NULL,
	"note" text,
	"bin_count" integer NOT NULL,
	"started_by" uuid NOT NULL,
	"started_at" timestamp with time zone NOT NULL,
	"approved_by" uuid,
	"approved_at" timestamp with time zone,
	"closed_by" uuid,
	"closed_at" timestamp with time zone,
	"abandoned_by" uuid,
	"abandoned_at" timestamp with time zone,
	"abandon_note" text,
	"device_writes" integer DEFAULT 0 NOT NULL,
	"posted_count" integer,
	"unposted_count" integer,
	"unposted" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "count_tasks" ADD COLUMN "stock_take_id" uuid;--> statement-breakpoint
ALTER TABLE "count_tasks" ADD COLUMN "cancelled_by" uuid;--> statement-breakpoint
ALTER TABLE "count_tasks" ADD COLUMN "cancelled_at" timestamp with time zone;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "stock_freeze_bins_tenant_bin_unique" ON "stock_freeze_bins" USING btree ("tenant_id","bin_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "stock_freeze_bins_tenant_take_idx" ON "stock_freeze_bins" USING btree ("tenant_id","stock_take_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "stock_takes_tenant_wh_status_idx" ON "stock_takes" USING btree ("tenant_id","warehouse_id","status");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "count_tasks_stock_take_status_idx" ON "count_tasks" USING btree ("tenant_id","stock_take_id","status") WHERE stock_take_id is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "count_tasks_tenant_created_at_id_idx" ON "count_tasks" USING btree ("tenant_id","created_at","id");
--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ────────────────────────
ALTER TABLE "stock_takes" ADD CONSTRAINT "stock_takes_status_check" CHECK (
	"status" IS NOT NULL AND "status" IN ('counting','posting','closed','abandoned')
);--> statement-breakpoint
ALTER TABLE "stock_takes" ADD CONSTRAINT "stock_takes_bin_count_check" CHECK (
	"bin_count" > 0
);--> statement-breakpoint
-- The lifecycle pairing: approved_* set iff posting or closed; closed_*,
-- posted_count and unposted_count set iff closed; abandoned_* set iff abandoned.
ALTER TABLE "stock_takes" ADD CONSTRAINT "stock_takes_lifecycle_pairing" CHECK (
	(("approved_by" IS NOT NULL AND "approved_at" IS NOT NULL) = ("status" IS NOT NULL AND "status" IN ('posting','closed')))
	AND ("approved_by" IS NULL) = ("approved_at" IS NULL)
	AND (("closed_by" IS NOT NULL AND "closed_at" IS NOT NULL AND "posted_count" IS NOT NULL AND "unposted_count" IS NOT NULL) = ("status" IS NOT NULL AND "status" = 'closed'))
	AND ("closed_by" IS NULL) = ("closed_at" IS NULL)
	AND ("closed_at" IS NULL) = ("posted_count" IS NULL)
	AND ("closed_at" IS NULL) = ("unposted_count" IS NULL)
	AND (("abandoned_by" IS NOT NULL AND "abandoned_at" IS NOT NULL) = ("status" IS NOT NULL AND "status" = 'abandoned'))
	AND ("abandoned_by" IS NULL) = ("abandoned_at" IS NULL)
);--> statement-breakpoint
ALTER TABLE "stock_takes" ADD CONSTRAINT "stock_takes_device_writes_check" CHECK (
	"device_writes" >= 0
);--> statement-breakpoint
ALTER TABLE "stock_freeze_bins" ADD CONSTRAINT "stock_freeze_bins_device_writes_check" CHECK (
	"device_writes" >= 0
);--> statement-breakpoint
ALTER TABLE "count_tasks" DROP CONSTRAINT "count_tasks_status_check";--> statement-breakpoint
ALTER TABLE "count_tasks" ADD CONSTRAINT "count_tasks_status_check" CHECK (
	"status" IN ('pending','completed','cancelled')
) NOT VALID;--> statement-breakpoint
ALTER TABLE "count_tasks" ADD CONSTRAINT "count_tasks_cancelled_pairing" CHECK (
	("status" = 'cancelled') = ("cancelled_at" IS NOT NULL)
) NOT VALID;--> statement-breakpoint
-- ── hand-amended: RLS (the standard fail-closed shape) ────────────────────
ALTER TABLE "stock_takes" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "stock_takes_tenant_isolation" ON "stock_takes"
  USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
  WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
ALTER TABLE "stock_freeze_bins" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "stock_freeze_bins_tenant_isolation" ON "stock_freeze_bins"
  USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
  WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0106 model) ────────────────────────
-- Made-up uuids. (a) The two count_tasks CHECKs are present and NOT VALID.
-- (b) The accepted shapes are inserted first and rolled back by a sentinel
-- exception, so a CHECK that refused everything fails the migration. (c) Each
-- refused shape runs in its own subtransaction and must be refused BY ITS
-- NAMED CONSTRAINT — CHECKs run in name order (guide §3), so each probe row
-- satisfies every CHECK named before its target: `count_tasks_cancelled_pairing`
-- sorts first on count_tasks (an unknown status with no cancelled_at passes it),
-- `stock_takes_bin_count_check` before `stock_takes_status_check`.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
	n int;
BEGIN
	-- (a)
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE contype = 'c'
	   AND NOT convalidated
	   AND conrelid = 'public.count_tasks'::regclass
	   AND conname IN ('count_tasks_status_check', 'count_tasks_cancelled_pairing');
	IF n <> 2 THEN
		RAISE EXCEPTION 'migration 0107: expected count_tasks_status_check and count_tasks_cancelled_pairing present and NOT VALID, found % so.', n;
	END IF;
	-- (b) accepted shapes: a take under every status; a freeze row; a pending,
	-- a completed and a cancelled task (a take's and a cycle count's).
	BEGIN
		INSERT INTO "stock_takes" ("id","tenant_id","warehouse_id","zone_ids","status","bin_count","started_by","started_at","approved_by","approved_at","closed_by","closed_at","posted_count","unposted_count","abandoned_by","abandoned_at")
		VALUES
			(gen_random_uuid(), t, w, NULL, 'counting', 1, u, now(), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
			(gen_random_uuid(), t, w, '["00000000-0000-7000-8000-000000000001"]'::jsonb, 'posting', 3000, u, now(), u, now(), NULL, NULL, NULL, NULL, NULL, NULL),
			(gen_random_uuid(), t, w, NULL, 'closed', 2, u, now(), u, now(), u, now(), 2, 0, NULL, NULL),
			(gen_random_uuid(), t, w, NULL, 'abandoned', 2, u, now(), NULL, NULL, NULL, NULL, NULL, NULL, u, now());
		INSERT INTO "stock_freeze_bins" ("id","tenant_id","warehouse_id","bin_id","bin_code","stock_take_id","frozen_at","device_writes")
		VALUES (gen_random_uuid(), t, w, gen_random_uuid(), 'A-01', gen_random_uuid(), now(), 0);
		INSERT INTO "count_tasks" ("id","tenant_id","warehouse_id","bin_id","status","origin","stock_take_id","cancelled_by","cancelled_at")
		VALUES
			(gen_random_uuid(), t, w, gen_random_uuid(), 'pending', 'on_demand', gen_random_uuid(), NULL, NULL),
			(gen_random_uuid(), t, w, gen_random_uuid(), 'completed', 'recount', NULL, NULL, NULL),
			(gen_random_uuid(), t, w, gen_random_uuid(), 'cancelled', 'scheduled', NULL, u, now()),
			(gen_random_uuid(), t, w, gen_random_uuid(), 'cancelled', 'on_demand', gen_random_uuid(), u, now());
		RAISE EXCEPTION USING ERRCODE = 'P0107', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0107: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0107' THEN
			NULL;
	END;
	-- (c) refused shapes, each by its named CHECK.
	FOREACH probe IN ARRAY ARRAY[
		'a take with an unknown status', 'a take with no bins', 'negative device writes',
		'closed without its stamps', 'counting with an approval', 'abandoned without its stamps',
		'cancelled without cancelled_at', 'pending with cancelled_at', 'a task with an unknown status'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'a take with an unknown status' THEN 'stock_takes_status_check'
			WHEN 'a take with no bins' THEN 'stock_takes_bin_count_check'
			WHEN 'closed without its stamps' THEN 'stock_takes_lifecycle_pairing'
			WHEN 'counting with an approval' THEN 'stock_takes_lifecycle_pairing'
			WHEN 'abandoned without its stamps' THEN 'stock_takes_lifecycle_pairing'
			WHEN 'negative device writes' THEN 'stock_freeze_bins_device_writes_check'
			WHEN 'a task with an unknown status' THEN 'count_tasks_status_check'
			ELSE 'count_tasks_cancelled_pairing'
		END;
		BEGIN
			CASE probe
				WHEN 'a take with an unknown status' THEN
					INSERT INTO "stock_takes" ("id","tenant_id","warehouse_id","status","bin_count","started_by","started_at")
					VALUES (gen_random_uuid(), t, w, 'frozen', 1, u, now());
				WHEN 'a take with no bins' THEN
					INSERT INTO "stock_takes" ("id","tenant_id","warehouse_id","status","bin_count","started_by","started_at")
					VALUES (gen_random_uuid(), t, w, 'counting', 0, u, now());
				WHEN 'closed without its stamps' THEN
					INSERT INTO "stock_takes" ("id","tenant_id","warehouse_id","status","bin_count","started_by","started_at","approved_by","approved_at")
					VALUES (gen_random_uuid(), t, w, 'closed', 1, u, now(), u, now());
				WHEN 'counting with an approval' THEN
					INSERT INTO "stock_takes" ("id","tenant_id","warehouse_id","status","bin_count","started_by","started_at","approved_by","approved_at")
					VALUES (gen_random_uuid(), t, w, 'counting', 1, u, now(), u, now());
				WHEN 'abandoned without its stamps' THEN
					INSERT INTO "stock_takes" ("id","tenant_id","warehouse_id","status","bin_count","started_by","started_at")
					VALUES (gen_random_uuid(), t, w, 'abandoned', 1, u, now());
				WHEN 'negative device writes' THEN
					INSERT INTO "stock_freeze_bins" ("id","tenant_id","warehouse_id","bin_id","bin_code","stock_take_id","frozen_at","device_writes")
					VALUES (gen_random_uuid(), t, w, gen_random_uuid(), 'A-02', gen_random_uuid(), now(), -1);
				WHEN 'cancelled without cancelled_at' THEN
					INSERT INTO "count_tasks" ("id","tenant_id","warehouse_id","bin_id","status","origin")
					VALUES (gen_random_uuid(), t, w, gen_random_uuid(), 'cancelled', 'on_demand');
				WHEN 'pending with cancelled_at' THEN
					INSERT INTO "count_tasks" ("id","tenant_id","warehouse_id","bin_id","status","origin","cancelled_at")
					VALUES (gen_random_uuid(), t, w, gen_random_uuid(), 'pending', 'on_demand', now());
				ELSE
					INSERT INTO "count_tasks" ("id","tenant_id","warehouse_id","bin_id","status","origin")
					VALUES (gen_random_uuid(), t, w, gen_random_uuid(), 'voided', 'on_demand');
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0107: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "stock_takes" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "stock_freeze_bins" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "count_tasks" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0107: a probe row survived.';
	END IF;
END $$;
